/* ========== v2: header and footer ========== */
function header(){const r=route()[0];const isApp=r==='app';document.body.classList.toggle('isapp',isApp);if(isApp)return;
 const nav=[['find',X('Find training','Cari latihan')],['ratings',X('Rated trainers','Jurulatih ditarafkan')],['providers',X('For providers','Untuk penyedia')],['for-trainers',X('For trainers','Untuk jurulatih')],['methodology',X('How ratings work','Cara penarafan')]];
 document.getElementById('banner').textContent=X('Prototype. Every trainer except the sample profile is fictional, their photos are AI-generated, and course dates and prices are samples.','Prototaip. Setiap jurulatih kecuali profil contoh adalah rekaan, foto mereka dijana AI, dan tarikh serta harga kursus adalah contoh.');
 const on=n=>r===n||(r==='trainer'&&n==='ratings')||(r==='course'&&n==='find');
 document.getElementById('mast').innerHTML=`<div class="mast__in"><a class="brand" href="#/">OSH<span>2</span>U</a><button class="menuBtn" data-act="menu" aria-expanded="false" aria-controls="mainNav">${X('Menu','Menu')}</button><nav class="nav" id="mainNav" aria-label="${X('Main','Utama')}">${nav.map(n=>`<a href="#/${n[0]}" class="${on(n[0])?'on':''}">${n[1]}</a>`).join('')}</nav><div class="navcta"><a class="btn btn--onDark" href="#/app">${X('Trainer app','Aplikasi jurulatih')}</a></div></div>`;
 document.getElementById('foot').innerHTML=`<div class="in"><div><b>OSH2U Sdn Bhd</b> <span class="mono">[${X('SSM NO. PENDING','NO. SSM BELUM DIDAFTAR')}]</span> · osh2u.my<br>${X('OSH2U is an independent rating platform for occupational safety and health trainers. It is not affiliated with DOSH (JKKP), NIOSH Malaysia, HRD Corp or any other body named on this site, and a rating does not replace any registration they require.','OSH2U ialah platform penarafan bebas untuk jurulatih keselamatan dan kesihatan pekerjaan. OSH2U tidak mempunyai kaitan dengan JKKP, NIOSH Malaysia, HRD Corp atau mana-mana badan lain yang dinamakan di laman ini, dan penarafan tidak menggantikan apa-apa pendaftaran yang diwajibkan oleh mereka.')}</div><div>${X('Data is held in Malaysia (Google Cloud, Kuala Lumpur). Criteria v0.3. Photos of the fictional trainers are AI-generated. The sample profile photo is used with permission. Topic photos from Unsplash.','Data disimpan di Malaysia (Google Cloud, Kuala Lumpur). Kriteria v0.3. Foto jurulatih rekaan dijana AI. Foto profil contoh digunakan dengan kebenaran. Foto topik daripada Unsplash.')}<br><a href="#/methodology">${X('How ratings work','Cara penarafan')}</a> · <a href="#/for-trainers">${X('Plans for trainers','Pelan untuk jurulatih')}</a> · <a href="#/admin">${X('Back office (demo)','Pejabat belakang (demo)')}</a><div class="build">${X('Build','Binaan')} 2026-11-08 v16</div></div></div>`;
 document.documentElement.lang=LANG==='ms'?'ms':'en'}
function langSwitch(){return `<div class="lang" role="group" aria-label="${X('Language','Bahasa')}"><button data-act="lang" data-v="en" class="${LANG==='en'?'on':''}" aria-pressed="${LANG==='en'}">EN</button><button data-act="lang" data-v="ms" class="${LANG==='ms'?'on':''}" aria-pressed="${LANG==='ms'}">BM</button></div>`}

/* ========== courses and class dates (samples) ========== */
const CITY={'Johor':'Johor Bahru','Kedah':'Alor Setar','Kelantan':'Kota Bharu','Melaka':'Melaka','Negeri Sembilan':'Seremban','Pahang':'Kuantan','Perak':'Ipoh','Perlis':'Kangar','Pulau Pinang':'George Town','Sabah':'Kota Kinabalu','Sarawak':'Kuching','Selangor':'Shah Alam','Terengganu':'Kuala Terengganu','WP Kuala Lumpur':'Kuala Lumpur','WP Labuan':'Labuan','WP Putrajaya':'Putrajaya'};
function nextDates(seed,count){const s=new Date(TODAY);s.setDate(s.getDate()+((8-s.getDay())%7||7));const out=[];let w=hash(seed)%3;for(let i=0;i<count;i++){w+=2+hash(seed+i)%3;const d=new Date(s);d.setDate(s.getDate()+w*7+1+hash(seed+'d'+i)%2);out.push(iso(d))}return out}
function appState(){const s=load('osh2u.app',null);return Object.assign({courses:[],boost:{},inbox:{},cal:{},claimed:false,qrUsed:false,availSet:false,cardOrdered:true},s||{})}
function appSave(o){save('osh2u.app',o)}
function allCourses(){const out=[];T.filter(t=>t.status!=='review').forEach(t=>t.courses.forEach((c,i)=>{const id=t.id+'-'+i;const mode=c[2];const price=Math.round((c[1]*360+hash(id)%5*40)/10)*10;
 out.push({id,t,title:c[0],days:c[1],mode,hrdc:c[3],spec:t.specs[Math.min(i,t.specs.length-1)],price,langs:t.langs,venue:mode===2?X('Online, live','Dalam talian, secara langsung'):CITY[t.state]||t.state,state:t.state,sessions:mode===1?[]:nextDates(id,mode===2?2:3)})}));
 const A=appState(),me=byId(DEMO);A.courses.forEach((c,i)=>out.push({id:'app-'+i,t:me,title:c.title,days:+c.days||1,mode:+c.mode,hrdc:!!c.hrdc,spec:c.spec,price:+c.price||0,langs:c.langs&&c.langs.length?c.langs:me.langs,venue:+c.mode===2?X('Online, live','Dalam talian, secara langsung'):(c.city||CITY[me.state]),state:me.state,sessions:c.date?[c.date]:[],mine:true}));
 return out}
const courseById=id=>allCourses().find(c=>c.id===id);
const nextOf=c=>c.sessions.filter(d=>daysTo(d)>=0).sort()[0];
const modeLabel=m=>V(MODES[m]);
function rm(n){return 'RM'+Number(n).toLocaleString('en-MY')}
function ccard(c,sp){const m=mark(c.t),nx=nextOf(c);
 return `<article class="ccard ${sp?'ccard--sp':''}">${sp?`<span class="pill pill--y">${X('Sponsored','Ditaja')}</span>`:''}<span class="small muted">${V(c.spec)}</span><h3><a href="#/course/${c.id}">${esc(c.title)}</a></h3>
 <div class="tr">${plate(c.t,'plate--sm')}<span><a href="#/trainer/${c.t.id}" style="color:var(--ink);font-weight:600;text-decoration:none">${esc(c.t.name)}</a><br>${m==='registered'?`<span class="small muted">${X('Collecting reviews','Mengumpul ulasan')}</span>`:starsum(c.t)}</span></div>
 <div class="meta"><span>📅 ${nx?fd(nx):X('In-house, on request','Dalaman, atas permintaan')}${c.sessions.length>1?` <span class="muted">+${c.sessions.length-1} ${X('more','lagi')}</span>`:''}</span><span>📍 ${esc(c.mode===1?X('At your workplace','Di tempat kerja anda'):c.venue)} · ${c.days} ${X(c.days>1?'days':'day','hari')}</span><span>🗣 ${c.langs.map(V).join(', ')}</span></div>
 <div class="foot"><span><span class="pr">${rm(c.price)}</span> <span class="small muted">${X('per person','seorang')}</span>${c.hrdc?`<br><span class="pill">${X('HRD Corp claimable','Boleh dituntut HRD Corp')}</span>`:''}</span><button class="btn btn--sm" data-act="enq" data-c="${c.id}">${X('Enquire','Tanya')}</button></div></article>`}

/* ========== home: for people looking for training ========== */
function home(){const cs=allCourses();const up=cs.filter(c=>nextOf(c)).sort((a,b)=>nextOf(a).localeCompare(nextOf(b))).slice(0,6);
 const top=T.filter(t=>mark(t).length<=3).sort((a,b)=>score(b)-score(a)).slice(0,4);
 const chips=[['OSH Coordinator (OSH-C)',X('OSH Coordinator','Penyelaras KKP')],['First aid, CPR and AED',X('First aid and CPR','Pertolongan cemas dan CPR')],['HIRARC and risk assessment','HIRARC'],['Confined space and gas testing',X('Confined space','Ruang terkurung')],['Working at height and scaffolding',X('Working at height','Kerja di tempat tinggi')],['Forklift and defensive driving',X('Forklift','Forklif')],['SHO examination preparation',X('SHO exam preparation','Persediaan peperiksaan SHO')]];
 return `<section class="hero"><p class="eyebrow" style="color:var(--y)">${X('OSH training, rated by the people who attended','Latihan KKP, ditarafkan oleh mereka yang hadir')}</p><h1>${X('Find safety training you can trust.','Cari latihan keselamatan yang boleh dipercayai.')}</h1><p class="lede">${X('Compare OSH courses and trainers across Malaysia. Every trainer’s credentials are checked at source, and every star comes from a verified participant. Free to search and enquire.','Bandingkan kursus dan jurulatih KKP di seluruh Malaysia. Kelayakan setiap jurulatih disemak di sumber, dan setiap bintang datang daripada peserta yang disahkan. Percuma untuk mencari dan bertanya.')}</p>
 <form class="search" id="homeSearch" role="search"><div><label class="f" for="hs1">${X('What training do you need?','Latihan apa yang anda perlukan?')}</label><select id="hs1" name="spec"><option value="">${X('Any topic','Semua topik')}</option>${SPECS.map(s=>`<option value="${esc(s)}">${V(s)}</option>`).join('')}</select></div><div><label class="f" for="hs2">${X('Where?','Di mana?')}</label><select id="hs2" name="state"><option value="">${X('Anywhere in Malaysia','Seluruh Malaysia')}</option>${STATES.map(s=>`<option>${s}</option>`).join('')}</select></div><button class="btn btn--y" type="submit">${X('Search','Cari')}</button></form>
 <div class="qchips">${chips.map(c=>`<a href="#/find" data-act="qchip" data-v="${esc(c[0])}">${c[1]}</a>`).join('')}</div></section>
 <section class="panel" style="display:grid;grid-template-columns:auto 1fr auto;gap:16px;align-items:center"><span style="font-size:30px" aria-hidden="true">⚠️</span><div><b>${X('Five or more employees? You need an OSH Coordinator.','Lima pekerja atau lebih? Anda perlukan Penyelaras KKP.')}</b><br><span class="small">${X('Since 1 June 2024, section 29A of OSHA requires workplaces with five or more employees to appoint one, with fines of up to RM50,000. Find a rated OSH-C trainer near you.','Sejak 1 Jun 2024, seksyen 29A Akta KKP mewajibkan tempat kerja dengan lima pekerja atau lebih melantik seorang, dengan denda sehingga RM50,000. Cari jurulatih OSH-C yang ditarafkan berhampiran anda.')}</span></div><a class="btn btn--ghost btn--sm" href="#/find" data-act="qchip" data-v="OSH Coordinator (OSH-C)">${X('See OSH-C courses','Lihat kursus OSH-C')}</a></section>
 <section class="sec"><div style="display:flex;justify-content:space-between;align-items:end;gap:10px;flex-wrap:wrap"><div><p class="eyebrow">${X('Upcoming public classes','Kelas awam akan datang')}</p><h2>${X('Book a seat for your team','Tempah tempat untuk pasukan anda')}</h2></div><a href="#/find">${X('See all training','Lihat semua latihan')} →</a></div><div class="cgrid">${up.map(c=>ccard(c)).join('')}</div></section>
 <section class="sec"><p class="eyebrow">${X('How it works','Cara ia berfungsi')}</p><div class="steps3">${[[X('Search','Cari'),X('By topic, state, date and language. In-house courses come to your workplace.','Mengikut topik, negeri, tarikh dan bahasa. Kursus dalaman diadakan di tempat kerja anda.')],[X('Compare on evidence','Bandingkan berdasarkan bukti'),X('One public grade per trainer, built from verified participant stars and credentials checked with the issuing body.','Satu gred awam bagi setiap jurulatih, dibina daripada bintang peserta yang disahkan dan kelayakan yang disemak dengan badan pengeluar.')],[X('Enquire for free','Tanya secara percuma'),X('Send an enquiry in a minute. The trainer replies to you directly, and there is no booking fee.','Hantar pertanyaan dalam seminit. Jurulatih membalas terus kepada anda, dan tiada yuran tempahan.')]].map((s,i)=>`<div class="panel"><span class="n">${i+1}</span><h3>${s[0]}</h3><p class="small">${s[1]}</p></div>`).join('')}</div></section>
 <section class="sec"><div style="display:flex;justify-content:space-between;align-items:end;gap:10px;flex-wrap:wrap"><div><p class="eyebrow">${X('Top-rated trainers','Jurulatih penarafan tertinggi')}</p><h2>${X('Rated on what participants said','Ditarafkan berdasarkan kata peserta')}</h2></div><a href="#/ratings">${X('All trainers','Semua jurulatih')} →</a></div><div class="grid4">${top.map(t=>`<a class="panel" href="#/trainer/${t.id}" style="text-decoration:none;color:var(--ink)"><div style="display:flex;justify-content:space-between;align-items:start">${plate(t,'plate--sm')}${t.sample?`<span class="pill pill--y">${X('Sample','Contoh')}</span>`:''}</div><h3 style="margin:10px 0 2px;font-size:15.5px">${esc(t.name)}</h3><p class="small muted" style="margin:0 0 6px">${V(t.specs[0])} · ${t.state}</p>${starsum(t)}</a>`).join('')}</div></section>
 <section class="sec grid2"><div class="panel"><h2>${X('Why employers trust the grade','Mengapa majikan mempercayai gred ini')}</h2><ul class="ticks"><li>${X('Stars come only from people who attended, confirmed by a code on their phone','Bintang hanya daripada mereka yang hadir, disahkan dengan kod di telefon mereka')}</li><li>${X('Credentials are checked with the body that issued them','Kelayakan disemak dengan badan yang mengeluarkannya')}</li><li>${X('No trainer can pay for a grade or a better position','Tiada jurulatih boleh membayar untuk gred atau kedudukan yang lebih baik')}</li></ul><a href="#/methodology">${X('How ratings work','Cara penarafan')}</a></div>
 <div class="panel" style="background:var(--gl)"><h2>${X('Are you an OSH trainer?','Adakah anda jurulatih KKP?')}</h2><p>${X('Get verified, collect participant stars, list your courses and carry your OSH2U ID card. Free during the pilot.','Dapatkan pengesahan, kumpul bintang peserta, senaraikan kursus anda dan bawa kad ID OSH2U anda. Percuma sepanjang tempoh perintis.')}</p><div class="btns"><a class="btn" href="#/app/join">${X('Join as a trainer','Sertai sebagai jurulatih')}</a><a class="btn btn--ghost" href="#/for-trainers">${X('What you get','Apa yang anda dapat')}</a></div></div></section>`}

/* ========== find training ========== */
let FC={q:'',spec:'',state:'',month:'',mode:'',hrdc:false,minG:'',sort:'soon'};
function findResults(){const q=FC.q.trim().toLowerCase();const gi=g=>['AAA','AA','A','BBB','BB','B'].indexOf(g);
 let cs=allCourses().filter(c=>{if(q&&!(c.title+' '+c.t.name+' '+c.spec+' '+(VOCAB[c.spec]||'')+' '+c.venue).toLowerCase().includes(q))return false;if(FC.spec&&c.spec!==FC.spec)return false;if(FC.state&&c.state!==FC.state&&c.mode!==2)return false;if(FC.mode!==''&&String(c.mode)!==FC.mode)return false;if(FC.hrdc&&!c.hrdc)return false;
  if(FC.month){if(c.mode===1)return true;if(!c.sessions.some(d=>d.slice(0,7)===FC.month))return false}
  if(FC.minG){const m=mark(c.t);if(gi(m)<0||gi(m)>gi(FC.minG))return false}return true});
 const sk=c=>nextOf(c)||'9999';if(FC.sort==='soon')cs.sort((a,b)=>sk(a).localeCompare(sk(b)));if(FC.sort==='rating')cs.sort((a,b)=>(mark(b.t).length<=3?score(b.t):0)-(mark(a.t).length<=3?score(a.t):0));if(FC.sort==='price')cs.sort((a,b)=>a.price-b.price);
 const A=appState();const sp=cs.filter(c=>c.mine&&A.boost[c.id]);
 return `${sp.length?`<p class="eyebrow" style="margin-top:6px">${X('Sponsored','Ditaja')}</p><div class="cgrid" style="margin-bottom:18px">${sp.map(c=>ccard(c,true)).join('')}</div>`:''}<p class="small muted">${cs.length} ${X('courses','kursus')}</p><div class="cgrid">${cs.map(c=>ccard(c)).join('')}</div>${cs.length?'':`<div class="panel">${X('Nothing matches yet. Try a wider area, or ask for an in-house course.','Belum ada yang sepadan. Cuba kawasan yang lebih luas, atau minta kursus dalaman.')}</div>`}
 <p class="small muted" style="margin-top:14px">${X('Sponsored courses are marked and sit apart from the results. Paying never changes a trainer’s grade or their place in the list.','Kursus ditaja ditanda dan diletakkan berasingan daripada keputusan. Bayaran tidak sekali-kali mengubah gred jurulatih atau kedudukan mereka dalam senarai.')}</p>`}
function find(){const months=[0,1,2].map(i=>{const d=new Date(TODAY.getFullYear(),TODAY.getMonth()+i,1);return [iso(d).slice(0,7),d.toLocaleDateString(LANG==='ms'?'ms-MY':'en-GB',{month:'long',year:'numeric'})]});
 return `<p class="eyebrow">${X('Find training','Cari latihan')}</p><h1>${X('OSH courses near you','Kursus KKP berhampiran anda')}</h1>
 <div class="panel"><div class="fbar"><div class="q"><label class="f" for="fc1">${X('Search','Carian')}</label><input id="fc1" type="text" data-fc="q" value="${esc(FC.q)}" placeholder="${X('Course, trainer or town','Kursus, jurulatih atau bandar')}"></div><div><label class="f" for="fc2">${X('Topic','Topik')}</label><select id="fc2" data-fc="spec"><option value="">${X('Any topic','Semua topik')}</option>${SPECS.map(s=>`<option value="${esc(s)}" ${FC.spec===s?'selected':''}>${V(s)}</option>`).join('')}</select></div><div><label class="f" for="fc3">${X('State','Negeri')}</label><select id="fc3" data-fc="state"><option value="">${X('Anywhere','Di mana-mana')}</option>${STATES.map(s=>`<option ${FC.state===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label class="f" for="fc4">${X('When','Bila')}</label><select id="fc4" data-fc="month"><option value="">${X('Any time','Bila-bila masa')}</option>${months.map(m=>`<option value="${m[0]}" ${FC.month===m[0]?'selected':''}>${m[1]}</option>`).join('')}</select></div></div>
 <div class="fbar2"><select aria-label="${X('Format','Format')}" data-fc="mode" style="width:auto"><option value="">${X('Any format','Semua format')}</option>${[0,2,1].map(m=>`<option value="${m}" ${FC.mode===String(m)?'selected':''}>${modeLabel(m)}</option>`).join('')}</select><select aria-label="${X('Minimum grade','Gred minimum')}" data-fc="minG" style="width:auto"><option value="">${X('Any grade','Semua gred')}</option>${['AAA','AA','A','BBB'].map(g=>`<option value="${g}" ${FC.minG===g?'selected':''}>${g} ${X('and above','dan ke atas')}</option>`).join('')}</select><select aria-label="${X('Sort by','Isih mengikut')}" data-fc="sort" style="width:auto">${[['soon',X('Soonest first','Terawal dahulu')],['rating',X('Best rated','Penarafan terbaik')],['price',X('Lowest price','Harga terendah')]].map(o=>`<option value="${o[0]}" ${FC.sort===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select><label class="chk" style="margin:0"><input type="checkbox" data-fc="hrdc" ${FC.hrdc?'checked':''}> ${X('HRD Corp claimable','Boleh dituntut HRD Corp')}</label></div></div>
 <div id="findR" style="margin-top:16px">${findResults()}</div>`}

/* ========== course page ========== */
function coursePage(id){const c=courseById(id);if(!c)return `<h1>${X('Course not found','Kursus tidak ditemui')}</h1><a href="#/find">${X('Back to search','Kembali ke carian')}</a>`;const t=c.t,m=mark(t);
 return `<p class="small"><a href="#/find">${X('Find training','Cari latihan')}</a> / ${V(c.spec)}</p><div class="grid2"><div><p class="eyebrow">${V(c.spec)}</p><h1>${esc(c.title)}</h1><p class="lede">${c.days} ${X(c.days>1?'days':'day','hari')} · ${modeLabel(c.mode)} · ${c.langs.map(V).join(', ')}</p>
 <div class="panel"><h3>${c.mode===1?X('In-house at your workplace','Dalaman di tempat kerja anda'):X('Upcoming classes','Kelas akan datang')}</h3>${c.mode===1?`<p>${X('The trainer comes to your site. Tell them your dates and group size.','Jurulatih datang ke premis anda. Beritahu tarikh dan saiz kumpulan anda.')}</p><button class="btn" data-act="enq" data-c="${c.id}">${X('Request in-house','Minta kursus dalaman')}</button>`:c.sessions.map(d=>`<div class="sess"><div><b>${fd(d,{weekday:'short',day:'numeric',month:'long',year:'numeric'})}</b><br><span class="small muted">📍 ${esc(c.venue)}</span></div><button class="btn btn--sm" data-act="enq" data-c="${c.id}" data-d="${d}">${X('Enquire','Tanya')}</button></div>`).join('')+`<p class="small" style="margin-top:12px">${X('Need it for your whole team?','Perlukan untuk seluruh pasukan?')} <a href="#" data-act="enq" data-c="${c.id}" data-inhouse="1">${X('Ask for an in-house class','Minta kelas dalaman')}</a></p>`}</div>
 <div class="panel" style="margin-top:14px"><dl class="kv"><dt>${X('Fee','Yuran')}</dt><dd><b class="mono">${rm(c.price)}</b> ${X('per person','seorang')} <span class="small muted">(${X('sample','contoh')})</span></dd><dt>${X('HRD Corp','HRD Corp')}</dt><dd>${c.hrdc?X('Claimable. Ask the trainer for the trainer pack for your grant application.','Boleh dituntut. Minta pakej jurulatih untuk permohonan geran anda.'):X('Not claimable','Tidak boleh dituntut')}</dd><dt>${X('Language','Bahasa')}</dt><dd>${c.langs.map(V).join(', ')}</dd><dt>${X('Topic','Topik')}</dt><dd>${V(c.spec)}</dd></dl></div></div>
 <aside><div class="panel"><p class="eyebrow">${X('Your trainer','Jurulatih anda')}</p><div class="who"><div class="av">${initials(t.name)}</div><div><a href="#/trainer/${t.id}">${esc(t.name)}</a><small>${V(t.type)} · ${t.state}</small></div></div><div style="display:flex;gap:14px;align-items:center;margin:12px 0">${plate(t,'plate--lg')}<div>${m==='registered'?`<b>${X('Collecting reviews','Mengumpul ulasan')}: ${nRev(t)} ${X('of','daripada')} 10</b>`:starsum(t)}<div>${outlook(t)}</div></div></div><p class="small">${P(t.sum)}</p><ul class="ticks small">${t.creds.slice(0,3).map(x=>`<li>${V(x)}</li>`).join('')}</ul><a class="btn btn--ghost btn--sm" href="#/trainer/${t.id}">${X('Full rating report','Laporan penarafan penuh')}</a></div>
 <p class="small muted" style="margin-top:10px">${X('Enquiries are free. OSH2U takes no commission on bookings.','Pertanyaan adalah percuma. OSH2U tidak mengambil komisen ke atas tempahan.')}</p></aside></div>`}

/* ========== for employers ========== */
function employers(){return `<p class="eyebrow">${X('For employers and HR','Untuk majikan dan sumber manusia')}</p><h1>${X('Choose OSH training on evidence.','Pilih latihan KKP berdasarkan bukti.')}</h1><p class="lede">${X('Search, compare and enquire for free. No booking fees, no commission, and no paid placement in the trainer list.','Cari, bandingkan dan tanya secara percuma. Tiada yuran tempahan, tiada komisen, dan tiada kedudukan berbayar dalam senarai jurulatih.')}</p>
 <div class="grid3"><div class="panel price price--hl"><span class="pill">${X('Free, always','Sentiasa percuma')}</span><h3 style="margin:0">${X('Employer','Majikan')}</h3><div class="amt">RM0</div><ul><li>${X('Search every course and trainer','Cari setiap kursus dan jurulatih')}</li><li>${X('Full rating reports and verified credentials','Laporan penarafan penuh dan kelayakan yang disahkan')}</li><li>${X('Unlimited enquiries to trainers','Pertanyaan tanpa had kepada jurulatih')}</li></ul><a class="btn btn--sm" href="#/find">${X('Find training','Cari latihan')}</a></div>
 <div class="panel price"><span class="pill pill--grey">${X('Planned for 2027','Dirancang untuk 2027')}</span><h3 style="margin:0">${X('Employer Team','Pasukan Majikan')}</h3><div class="amt">RM79 <small>${X('a month','sebulan')}</small></div><ul><li>${X('Training records for your staff, with certificate expiry reminders','Rekod latihan kakitangan, dengan peringatan tamat tempoh sijil')}</li><li>${X('Shortlists, side-by-side compare and team seats','Senarai pendek, perbandingan dan tempat duduk pasukan')}</li><li>${X('One invoice for procurement','Satu invois untuk perolehan')}</li></ul><p class="small muted" style="margin:0">${X('Employers who join during the pilot get it free for their first year.','Majikan yang menyertai semasa tempoh perintis mendapatnya percuma untuk tahun pertama.')}</p></div>
 <div class="panel price"><span class="pill pill--grey">${X('Planned for 2027','Dirancang untuk 2027')}</span><h3 style="margin:0">${X('Training providers','Penyedia latihan')}</h3><div class="amt">RM199 <small>${X('a month','sebulan')}</small></div><ul><li>${X('A provider page linked to your trainers','Halaman penyedia yang dipautkan kepada jurulatih anda')}</li><li>${X('Upload class lists so every participant gets a review link','Muat naik senarai kelas supaya setiap peserta mendapat pautan ulasan')}</li><li>${X('Course and CEP listings, marked as listings','Penyenaraian kursus dan CEP, ditanda sebagai penyenaraian')}</li></ul></div></div>
 <section class="sec panel"><h2>${X('Your OSH Coordinator duty','Kewajipan Penyelaras KKP anda')}</h2><p>${X('Since 1 June 2024, workplaces with five or more employees must appoint an OSH Coordinator (OSHA section 29A), with fines of up to RM50,000. The coordinator needs training, and OSH2U shows you who delivers it well.','Sejak 1 Jun 2024, tempat kerja dengan lima pekerja atau lebih mesti melantik Penyelaras KKP (seksyen 29A Akta KKP), dengan denda sehingga RM50,000. Penyelaras memerlukan latihan, dan OSH2U menunjukkan siapa yang menyampaikannya dengan baik.')}</p><a class="btn" href="#/find" data-act="qchip" data-v="OSH Coordinator (OSH-C)">${X('Find OSH-C training','Cari latihan OSH-C')}</a></section>`}

/* ========== for trainers (public) ========== */
function forTrainers(){const row=(f,a,b)=>`<tr><td>${f}</td><td class="c">${a}</td><td class="c">${b}</td></tr>`;const y='✓',n='-';
 return `<p class="eyebrow">${X('For trainers','Untuk jurulatih')}</p><h1>${X('Get verified. Get rated. Get booked.','Disahkan. Ditarafkan. Ditempah.')}</h1><p class="lede">${X('Your rating is always free. Join during the pilot and everything else is free too, including your OSH2U NFC card.','Penarafan anda sentiasa percuma. Sertai semasa tempoh perintis dan semua yang lain juga percuma, termasuk kad NFC OSH2U anda.')}</p><div class="btns"><a class="btn btn--y" href="#/app/join">${X('Start onboarding','Mulakan pendaftaran')}</a><a class="btn btn--ghost" href="#/app">${X('Try the trainer app','Cuba aplikasi jurulatih')}</a></div>
 <div class="grid2" style="margin-top:20px"><div class="panel"><h2>${X('Plans','Pelan')}</h2><div class="scroll"><table class="planT"><thead><tr><th></th><th class="c">${X('Free','Percuma')}</th><th class="c">Pro<br><span class="mono small">RM29/${X('mo','bln')}</span></th></tr></thead><tbody>
 ${row(X('Verified profile, grade and rating report','Profil disahkan, gred dan laporan penarafan'),y,y)}${row(X('Review QR code and class codes','Kod QR ulasan dan kod kelas'),y,y)}${row(X('Digital ID','ID digital'),y,y)}${row(X('Certificate reminders, points and calendar','Peringatan sijil, mata dan kalendar'),y,y)}${row(X('Employer enquiries','Pertanyaan majikan'),y,y)}${row(X('Published courses','Kursus diterbitkan'),'2',X('Unlimited','Tanpa had'))}${row(X('Enquiry and page-view stats','Statistik pertanyaan dan paparan'),n,y)}${row(X('Calendar sync, CEP and HRD Corp export','Penyegerakan kalendar, eksport CEP dan HRD Corp'),n,y)}${row(X('Trainer pack PDF','PDF pakej jurulatih'),n,y)}${row(X('One course boost a month','Satu promosi kursus sebulan'),n,y)}</tbody></table></div><p class="small muted">${X('Pro is RM290 a year paid annually. A course boost on the free plan is RM20 for 30 days, shown as Sponsored. Neither changes your grade or your place in the trainer list.','Pro ialah RM290 setahun jika dibayar tahunan. Promosi kursus pada pelan percuma ialah RM20 untuk 30 hari, dipaparkan sebagai Ditaja. Kedua-duanya tidak mengubah gred atau kedudukan anda dalam senarai jurulatih.')}</p></div>
 <div><div class="panel" style="background:var(--gl)"><span class="pill pill--y">${X('Founding trainers','Jurulatih perintis')}</span><h2 style="margin-top:8px">${X('Join in the pilot','Sertai semasa perintis')}</h2><ul class="ticks"><li>${X('Pro free until the end of our first year','Pro percuma sehingga akhir tahun pertama kami')}</li><li>${X('Your NFC card free, posted when you are verified','Kad NFC anda percuma, dihantar sebaik sahaja disahkan')}</li><li>${X('Pro at RM19 a month for life after that','Pro pada RM19 sebulan seumur hidup selepas itu')}</li><li>${X('A founding number on your card','Nombor perintis pada kad anda')}</li></ul></div>
 <div class="panel" style="margin-top:14px"><h3>${X('Your OSH2U NFC card','Kad NFC OSH2U anda')}</h3><p class="small">${X('Tap it on any phone and your live rating opens, with no app and no scanning. It is cryptographically signed, so it cannot be copied, and a QR code on the back covers phones without NFC.','Ketik pada mana-mana telefon dan penarafan semasa anda terbuka, tanpa aplikasi dan tanpa imbasan. Ia ditandatangani secara kriptografi, jadi tidak boleh disalin, dan kod QR di belakang untuk telefon tanpa NFC.')}</p><p class="small muted">${X('Free in the pilot. After that RM30, or free with Pro paid annually.','Percuma semasa perintis. Selepas itu RM30, atau percuma dengan Pro tahunan.')}</p></div></div></div>
 <section class="sec"><h2>${X('Onboarding takes about 10 minutes on your phone','Pendaftaran mengambil kira-kira 10 minit di telefon anda')}</h2><div class="steps3">${[[X('Sign up and add credentials','Daftar dan tambah kelayakan'),X('Photos of your certificates are enough to start.','Gambar sijil anda sudah memadai untuk bermula.')],[X('We verify at source','Kami sahkan di sumber'),X('About 5 working days. Your card ships once you are verified.','Kira-kira 5 hari bekerja. Kad anda dihantar sebaik sahaja disahkan.')],[X('List courses and collect stars','Senaraikan kursus dan kumpul bintang'),X('Employers find your classes, and every session adds to your grade.','Majikan menemui kelas anda, dan setiap sesi menambah gred anda.')]].map((s,i)=>`<div class="panel"><span class="n">${i+1}</span><h3>${s[0]}</h3><p class="small">${s[1]}</p></div>`).join('')}</div></section>`}

/* ========== enquiry dialog ========== */
let ENQ=null;
function openEnq(cid,date,inhouse){const c=cid?courseById(cid):null;const t=c?c.t:(byId(route()[1])||byId('ahmad-fakhrul-anuar'));ENQ={course:c?c.id:null,trainer:t.id};
 const m=document.createElement('div');m.className='modal';m.id='modal';m.innerHTML=`<div class="modal__box" role="dialog" aria-modal="true" aria-labelledby="mh"><h2 id="mh">${c?esc(c.title):X('Enquire with','Tanya')+' '+esc(t.short||t.name)}</h2><p class="small muted">${c?esc(t.name)+' · ':''}${X('Free. The trainer replies to you directly.','Percuma. Jurulatih membalas terus kepada anda.')}</p>
 <form id="reqF" class="form"><div><label class="f" for="r2">${X('Your name','Nama anda')}</label><input id="r2" name="name" type="text" required autocomplete="name"></div><div><label class="f" for="r1">${X('Company','Syarikat')}</label><input id="r1" name="company" type="text" required autocomplete="organization"></div><div><label class="f" for="r3">${X('Email','E-mel')}</label><input id="r3" name="email" type="email" required autocomplete="email"></div><div><label class="f" for="r4">${X('Mobile number','Nombor telefon bimbit')}</label><input id="r4" name="phone" type="tel" autocomplete="tel"></div><div><label class="f" for="r5">${X('How many people?','Berapa orang?')}</label><input id="r5" name="pax" type="number" min="1" inputmode="numeric"></div><div><label class="f" for="r6">${X('Preferred date','Tarikh pilihan')}</label><input id="r6" name="date" type="date" value="${date||''}"></div><div class="full"><label class="f" for="r7">${X('Anything else?','Apa-apa lagi?')}</label><textarea id="r7" name="msg">${inhouse?X('We would like an in-house class at our workplace.','Kami mahukan kelas dalaman di tempat kerja kami.'):''}</textarea></div>
 <div class="full btns"><button class="btn" type="submit">${X('Send enquiry','Hantar pertanyaan')}</button><button class="btn btn--ghost" type="button" data-act="close">${X('Cancel','Batal')}</button></div></form></div>`;
 document.body.appendChild(m);setTimeout(()=>{const f=document.getElementById('r2');if(f)f.focus()},30)}

/* ========== trainer app (mobile first) ========== */
const DEMO='ahmad-fakhrul-anuar';
const ICON={home:'<path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',courses:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 4v5"/>',id:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="8" cy="12" r="2.5"/><path d="M13 10h6M13 14h4"/>',inbox:'<path d="M3 13l3-8h12l3 8v6H3z"/><path d="M3 13h5l1 2h6l1-2h5"/>',more:'<circle cx="5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="19" cy="12" r="1.6"/>'};
const svg=k=>`<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[k]}</svg>`;
const DEMO_INBOX=[{id:'i1',co:'Shah Alam Precision Parts (sample)',who:'Hazwan Ismail',pax:3,course:'ahmad-fakhrul-anuar-0',date:'2026-12-02',msg:['Three of our new SHOs should attend The Art of Becoming a Great SHO before our audit in January.','Three of our new SHOs should attend The Art of Becoming a Great SHO before our audit in January.']},{id:'i2',co:'Klang Port Logistics (sample)',who:'Priya Raman',pax:12,course:'ahmad-fakhrul-anuar-2',msg:['OSH-C for 12 supervisors, in-house at our Klang depot if possible.','OSH-C for 12 supervisors, in-house at our Klang depot if possible.']},{id:'i3',co:'Bangi Food Processing (sample)',who:'Tan Mei Ling',pax:5,course:'ahmad-fakhrul-anuar-1',msg:['Can five of our team join the SHO Starter Series in the new year?','Can five of our team join the SHO Starter Series in the new year?']}];
function inboxItems(){const leads=load('osh2u.leads',[]).filter(l=>l.trainer===DEMO).map((l,i)=>({id:'l'+i,co:l.company,who:l.name,pax:l.pax,course:l.course,date:l.date,msg:[l.msg||'-',l.msg||'-'],em:l.email}));return DEMO_INBOX.concat(leads)}
function onboard(A){const me=byId(DEMO);const myC=allCourses().filter(c=>c.t.id===DEMO);
 return [[X('Create your account','Cipta akaun anda'),'',true,''],[X('Profile and photo','Profil dan gambar'),'',true,''],[X('Upload credentials','Muat naik kelayakan'),X('2 credentials','2 kelayakan'),true,''],[X('Verification at source','Pengesahan di sumber'),X('Verified 21 Jul 2026','Disahkan 21 Jul 2026'),true,''],[X('Publish your first public class','Terbitkan kelas awam pertama anda'),X('So employers can find and book you','Supaya majikan boleh mencari dan menempah anda'),myC.some(c=>c.sessions.length),'#/app/course-new'],[X('Set your availability','Tetapkan ketersediaan anda'),'',A.availSet,'#/app/more/availability'],[X('Use your review QR code in a class','Gunakan kod QR ulasan anda dalam kelas'),X(`${nRev(me)} of 10 reviews towards your first grade`,`${nRev(me)} daripada 10 ulasan ke arah gred pertama anda`),A.qrUsed,'#/app/more/reviews'],[X('Claim your NFC card','Tuntut kad NFC anda'),X('Posted to you, free for founding trainers','Dihantar kepada anda, percuma untuk jurulatih perintis'),A.claimed,'#/app/id']]}
function appShell(sub,body){const A=appState();const unread=inboxItems().filter(i=>!A.inbox[i.id]).length;
 const items=[['',X('Home','Utama'),'home'],['courses',X('Courses','Kursus'),'courses'],['id',X('My ID','ID saya'),'id'],['inbox',X('Inbox','Peti masuk'),'inbox'],['more',X('More','Lagi'),'more']];
 const on=k=>(sub||'')===k||(k==='courses'&&sub==='course-new')||(k==='more'&&sub==='more');
 const link=(i,cls)=>`<a href="#/app${i[0]?'/'+i[0]:''}" class="${cls} ${on(i[0])?'on':''}" ${on(i[0])?'aria-current="page"':''}>${svg(i[2])}<span>${i[1]}</span>${i[0]==='inbox'&&unread?`<span class="badge">${unread}</span>`:''}</a>`;
 return `<div class="app"><aside class="app__rail"><a class="brand" href="#/">OSH<span>2</span>U<small>${X('TRAINER','JURULATIH')}</small></a>${items.map(i=>link(i,'it')).join('')}<div class="sp">${langSwitch()}<p><a href="#/" style="color:#A3A3A3">← ${X('Public site','Laman awam')}</a></p></div></aside>
 <header class="app__top"><a class="brand" href="#/">OSH<span>2</span>U<small>${X('TRAINER','JURULATIH')}</small></a>${langSwitch()}</header>
 <main class="app__main" id="appMain"><p class="small muted" style="margin:0 0 10px">${X('Demo account: Nur Aisyah Kamaruddin (fictional). Changes are saved in this browser only.','Akaun demo: Nur Aisyah Kamaruddin (rekaan). Perubahan disimpan dalam pelayar ini sahaja.')}</p>${body}</main>
 <nav class="app__nav" aria-label="${X('Trainer app','Aplikasi jurulatih')}">${items.map(i=>link(i,'')).join('')}</nav></div>`}
function appHome(){const A=appState(),me=byId(DEMO),ob=onboard(A),done=ob.filter(o=>o[2]).length;const n=nRev(me);
 return `<h1 style="font-size:26px">${X('Hi','Hai')} Nur Aisyah 👋</h1>
 <div class="card" style="background:var(--gd);color:#fff;border:0"><div style="display:flex;gap:14px;align-items:center">${plate(me)}<div><b>${X('Collecting reviews','Mengumpul ulasan')}: ${n} ${X('of','daripada')} 10</b><div class="small" style="color:#D9D9D9">${X('Two more verified reviews and your first grade is calculated. You see it 14 days before it is published.','Dua lagi ulasan yang disahkan dan gred pertama anda dikira. Anda melihatnya 14 hari sebelum diterbitkan.')}</div></div></div><div class="prog" style="background:rgba(255,255,255,.2)"><i style="width:${n*10}%"></i></div></div>
 <div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h3>${X('Finish setting up','Lengkapkan persediaan')}</h3><span class="mono small">${done}/${ob.length}</span></div><div class="prog"><i style="width:${done/ob.length*100}%"></i></div><ul class="check">${ob.map(o=>`<li class="${o[2]?'done':''}"><span class="ck" aria-hidden="true">${o[2]?'✓':''}</span><span class="tx">${o[0]}${o[1]?`<small>${o[1]}</small>`:''}</span>${!o[2]&&o[3]?`<a class="btn btn--sm" href="${o[3]}">${X('Do it','Buat')}</a>`:''}</li>`).join('')}</ul></div>
 <div class="stats"><div class="stat"><b>126</b><span>${X('Profile views, 30 days','Paparan profil, 30 hari')}</span></div><div class="stat"><b>${inboxItems().length}</b><span>${X('Enquiries','Pertanyaan')}</span></div><div class="stat"><b>${avg(me).toFixed(1)}</b><span>${X('Average stars','Purata bintang')}</span></div></div>
 <div class="card" style="margin-top:12px"><span class="pill pill--y">${X('Founding trainer','Jurulatih perintis')} #042</span><p style="margin:8px 0 0">${X('Pro is free for you until the end of our first year, then RM19 a month for life.','Pro percuma untuk anda sehingga akhir tahun pertama kami, kemudian RM19 sebulan seumur hidup.')} <a href="#/app/more/plan">${X('Your plan','Pelan anda')}</a></p></div>`}
function appCourses(){const A=appState(),cs=allCourses().filter(c=>c.t.id===DEMO);
 return `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h1 style="font-size:26px;margin:0">${X('My courses','Kursus saya')}</h1><a class="btn btn--sm btn--y" href="#/app/course-new">+ ${X('Add course','Tambah kursus')}</a></div><p class="small muted">${X('Published courses appear in Find training straight away. During the pilot you can publish as many as you like.','Kursus yang diterbitkan terus dipaparkan dalam Cari latihan. Semasa tempoh perintis anda boleh menerbitkan seberapa banyak yang anda mahu.')}</p>
 ${cs.map(c=>{const nx=nextOf(c),b=A.boost[c.id];const enq=inboxItems().filter(i=>i.course===c.id).length;return `<div class="card"><div style="display:flex;justify-content:space-between;gap:8px"><span class="pill">${X('Published','Diterbitkan')}</span>${b?`<span class="pill pill--y">${X('Sponsored until','Ditaja sehingga')} ${fd(b)}</span>`:''}</div><h3 style="margin-top:8px">${esc(c.title)}</h3><p class="small muted" style="margin:0">${modeLabel(c.mode)} · ${c.days} ${X(c.days>1?'days':'day','hari')} · ${rm(c.price)}</p><p class="small" style="margin:6px 0">📅 ${nx?fd(nx):X('No class date yet','Belum ada tarikh kelas')} · ✉️ ${enq} ${X('enquiries','pertanyaan')}</p><div class="btns" style="margin:0"><a class="btn btn--ghost btn--sm" href="#/course/${c.id}">${X('View public page','Lihat halaman awam')}</a>${c.mine||!b?`<button class="btn btn--ghost btn--sm" data-act="boost" data-c="${c.id}" ${b?'disabled':''}>${b?X('Boosted','Dipromosi'):X('Boost 30 days','Promosi 30 hari')}</button>`:''}</div></div>`}).join('')}
 <p class="small muted">${X('A boost shows your course in a Sponsored row on Find training for 30 days: free in the pilot, then RM20 or one a month with Pro. It never changes your grade or your place in the trainer list.','Promosi memaparkan kursus anda dalam baris Ditaja di Cari latihan selama 30 hari: percuma semasa perintis, kemudian RM20 atau satu sebulan dengan Pro. Ia tidak sekali-kali mengubah gred atau kedudukan anda dalam senarai jurulatih.')}</p>`}
function appCourseNew(){return `<p class="small"><a href="#/app/courses">← ${X('My courses','Kursus saya')}</a></p><h1 style="font-size:26px">${X('Add a course','Tambah kursus')}</h1><form id="courseF" class="card form"><div class="full"><label class="f" for="k1">${X('Course title','Tajuk kursus')}</label><input id="k1" name="title" type="text" required placeholder="${X('e.g. OSH Coordinator course','cth. Kursus Penyelaras KKP')}"></div><div class="full"><label class="f" for="k2">${X('Topic','Topik')}</label><select id="k2" name="spec" required>${SPECS.map(s=>`<option value="${esc(s)}">${V(s)}</option>`).join('')}</select></div><div><label class="f" for="k3">${X('Days','Hari')}</label><input id="k3" name="days" type="number" min="1" max="10" value="1" inputmode="numeric" required></div><div><label class="f" for="k4">${X('Fee per person (RM)','Yuran seorang (RM)')}</label><input id="k4" name="price" type="number" min="0" step="10" inputmode="numeric" required></div><div><label class="f" for="k5">${X('Format','Format')}</label><select id="k5" name="mode">${[0,2,1].map(m=>`<option value="${m}">${modeLabel(m)}</option>`).join('')}</select></div><div><label class="f" for="k6">${X('Town or venue','Bandar atau tempat')}</label><input id="k6" name="city" type="text" placeholder="Seremban"></div><div><label class="f" for="k7">${X('First class date','Tarikh kelas pertama')}</label><input id="k7" name="date" type="date"></div><div style="display:flex;align-items:end"><label class="chk"><input type="checkbox" name="hrdc" checked> ${X('HRD Corp claimable','Boleh dituntut HRD Corp')}</label></div><div class="full"><button class="btn btn--y" type="submit" style="width:100%">${X('Publish course','Terbitkan kursus')}</button></div></form>`}
function appId(){const A=appState(),me=byId(DEMO);
 return `<h1 style="font-size:26px">${X('My OSH2U ID','ID OSH2U saya')}</h1>
 <div class="card" style="text-align:center"><div style="display:flex;justify-content:center">${tcard(me)}</div><p class="mono small" style="color:var(--g);margin:12px 0 0">● ${X('Live','Langsung')} · ${X('checked','disemak')} ${new Date().toLocaleTimeString(LANG==='ms'?'ms-MY':'en-GB',{hour:'2-digit',minute:'2-digit'})}</p><p class="small muted">${X('Status and stars load from osh2u.my each time, so a screenshot cannot pass as current.','Status dan bintang dimuatkan dari osh2u.my setiap kali, jadi tangkapan skrin tidak boleh dianggap terkini.')}</p>
 <div class="btns" style="justify-content:center"><button class="btn btn--sm" data-act="copy" data-v="https://osh2u.my/t/OSH2U-0042">${X('Share my ID link','Kongsi pautan ID saya')}</button><button class="btn btn--ghost btn--sm" data-act="wallet">${X('Add to Apple Wallet','Tambah ke Apple Wallet')}</button><button class="btn btn--ghost btn--sm" data-act="wallet">${X('Add to Google Wallet','Tambah ke Google Wallet')}</button></div></div>
 <div class="card"><h3>${X('Your NFC card','Kad NFC anda')}</h3><p class="small">${X('Tap the card on any phone to open your live rating, no app needed. The chip signs every tap, so the card cannot be copied. The QR on the back works on phones without NFC.','Ketik kad pada mana-mana telefon untuk membuka penarafan semasa anda, tanpa aplikasi. Cip menandatangani setiap ketikan, jadi kad tidak boleh disalin. Kod QR di belakang untuk telefon tanpa NFC.')}</p>
 <div class="steps">${[[X('Verified','Disahkan'),true],[X('Printed','Dicetak'),true],[X('Posted','Dihantar'),true],[X('Claimed','Dituntut'),A.claimed]].map(s=>`<span class="${s[1]?'done':''}">${s[0].toUpperCase()}</span>`).join('')}</div>
 ${A.claimed?`<p>✓ ${X('Card active. If it is lost, cancel it here and the old card stops working at once.','Kad aktif. Jika hilang, batalkan di sini dan kad lama berhenti berfungsi serta-merta.')}</p><button class="btn btn--ghost btn--sm" data-act="lost">${X('Report a lost card','Laporkan kad hilang')}</button>`
 :`<form id="claimF"><label class="f" for="cc">${X('Claim code from the back of your card','Kod tuntutan di belakang kad anda')}</label><input id="cc" type="text" placeholder="K7Q4-M2XA" autocomplete="off" autocapitalize="characters"><div id="ccErr" class="small" style="color:var(--red);margin-top:6px" role="alert"></div><button class="btn" type="submit" style="margin-top:10px;width:100%">${X('Activate my card','Aktifkan kad saya')}</button></form><p class="hint">${X('Prototype: any 8 letters or numbers work.','Prototaip: mana-mana 8 huruf atau nombor boleh digunakan.')}</p>`}
 <p class="small muted">${X('Free for founding trainers. After the pilot a card is RM30, or free with Pro paid annually. Replacements are RM30.','Percuma untuk jurulatih perintis. Selepas tempoh perintis kad berharga RM30, atau percuma dengan Pro tahunan. Penggantian RM30.')}</p></div>`}
function tcard(t){return `<div class="tcard" role="img" aria-label="${X('OSH2U NFC card','Kad NFC OSH2U')}"><div class="tape"></div><div class="top"><b>OSH<span>2</span>U</b><small>VERIFIED TRAINER</small></div><div class="mid"><div class="ph">${initials(t.name)}</div><div style="text-align:left"><div class="nm">${esc(t.name)}</div><div class="sp">${V(t.specs[0])}</div><div class="ids"><div><small>OSH2U ID</small><b>OSH2U-0042</b></div><div><small>${X('VERIFIED SINCE','DISAHKAN SEJAK')}</small><b>JUL 2026</b></div></div></div></div><div class="fd">${X('FOUNDING TRAINER','JURULATIH PERINTIS')} 042 / 100</div><div class="ft"><span>◉ NFC · osh2u.my</span><span>${X('Tap or scan for live rating','Ketik atau imbas untuk penarafan')}</span></div></div>`}
function appInbox(){const A=appState(),items=inboxItems();
 return `<h1 style="font-size:26px">${X('Inbox','Peti masuk')}</h1><p class="small muted">${X('Enquiries from employers. Reply within 48 hours to keep your response rate high.','Pertanyaan daripada majikan. Balas dalam 48 jam untuk mengekalkan kadar respons anda.')}</p>${items.map(i=>{const st=A.inbox[i.id];const c=courseById(i.course);return `<div class="card"><div style="display:flex;justify-content:space-between;gap:8px"><b>${esc(i.co)}</b>${st?`<span class="pill ${st==='a'?'':'pill--grey'}">${st==='a'?X('Accepted','Diterima'):X('Declined','Ditolak')}</span>`:`<span class="pill pill--y">${X('New','Baharu')}</span>`}</div><p class="small muted" style="margin:4px 0">${esc(i.who)} · ${esc(i.pax||'-')} ${X('people','orang')}${c?' · '+esc(c.title):''}${i.date?' · '+fd(i.date):''}</p><p style="margin:6px 0">${esc(P(i.msg))}</p>${st?'':`<div class="btns" style="margin:0"><button class="btn btn--sm" data-act="ia" data-id="${i.id}">${X('Accept','Terima')}</button><button class="btn btn--ghost btn--sm" data-act="id" data-id="${i.id}">${X('Decline','Tolak')}</button></div>`}</div>`}).join('')}`}
function appMore(sub){const A=appState(),me=byId(DEMO);
 if(sub==='reviews')return `<p class="small"><a href="#/app/more">← ${X('More','Lagi')}</a></p><h1 style="font-size:26px">${X('Collect reviews','Kumpul ulasan')}</h1><div class="card" style="text-align:center">${qrSvg(QR.review,200,X('Review QR code','Kod QR ulasan'))}<p class="mono small">osh2u.my/r/${DEMO}</p><p class="small">${X('Show this on your last slide. Participants confirm with a code on their phone and rate in under a minute.','Paparkan pada slaid terakhir anda. Peserta mengesahkan dengan kod di telefon mereka dan menarafkan dalam masa kurang seminit.')}</p><button class="btn" data-act="qrused" style="width:100%">${X('Open a class code for today','Buka kod kelas untuk hari ini')}</button></div><div class="card">${starsum(me)}${me.rvw.map((r,i)=>`<div class="review">${stars(r.s)} <span class="small muted">${fd(r.d)}</span><p>${P(me.rt)[i]}</p></div>`).join('')}</div>`;
 if(sub==='availability')return `<p class="small"><a href="#/app/more">← ${X('More','Lagi')}</a></p><h1 style="font-size:26px">${X('Availability','Ketersediaan')}</h1><p class="small muted">${X('Tap a day to open or close it. Employers see open days on your public page.','Ketik hari untuk membuka atau menutupnya. Majikan melihat hari yang tersedia pada halaman awam anda.')}</p><div class="card">${calGrid('app',true,A.cal)}</div>`;
 if(sub==='certs'){const certs=[['DOSH Safety and Health Officer','2027-08-14'],['HRD Corp Accredited Trainer','2027-01-20']];return `<p class="small"><a href="#/app/more">← ${X('More','Lagi')}</a></p><h1 style="font-size:26px">${X('Certificates','Sijil')}</h1>${certs.map(c=>{const d=daysTo(c[1]);return `<div class="card"><b>${V(c[0])}</b><p class="small muted" style="margin:4px 0">${X('Valid until','Sah sehingga')} ${fd(c[1])} · ${X('Verified at source','Disahkan di sumber')}</p><span class="pill ${d<=90?'pill--y':''}">${d<=90?X(`Expires in ${d} days`,`Tamat tempoh dalam ${d} hari`):X('Valid','Sah')}</span></div>`}).join('')}<p class="small muted">${X('Reminders go out 90, 60 and 30 days before expiry, by email and WhatsApp.','Peringatan dihantar 90, 60 dan 30 hari sebelum tamat tempoh, melalui e-mel dan WhatsApp.')}</p>`}
 if(sub==='plan')return `<p class="small"><a href="#/app/more">← ${X('More','Lagi')}</a></p><h1 style="font-size:26px">${X('My plan','Pelan saya')}</h1><div class="card" style="background:var(--gl)"><span class="pill pill--y">${X('Founding trainer','Jurulatih perintis')} #042</span><h3 style="margin-top:8px">Pro · ${X('free','percuma')}</h3><p class="small">${X('Free until the end of our first year. After that RM19 a month, locked for life. Your rating and core tools are always free.','Percuma sehingga akhir tahun pertama kami. Selepas itu RM19 sebulan, dikunci seumur hidup. Penarafan dan alat utama anda sentiasa percuma.')}</p></div><a class="btn btn--ghost" href="#/for-trainers" style="width:100%">${X('Compare Free and Pro','Bandingkan Percuma dan Pro')}</a>`;
 const rows=[['reviews',X('Collect reviews','Kumpul ulasan'),X('QR code and class codes','Kod QR dan kod kelas')],['availability',X('Availability','Ketersediaan'),X('Open and close days','Buka dan tutup hari')],['certs',X('Certificates','Sijil'),X('Expiry reminders','Peringatan tamat tempoh')],['plan',X('My plan','Pelan saya'),X('Founding trainer, Pro free','Jurulatih perintis, Pro percuma')]];
 return `<h1 style="font-size:26px">${X('More','Lagi')}</h1><div class="card">${rows.map(r=>`<a class="listrow" href="#/app/more/${r[0]}"><span><b>${r[1]}</b><br><span class="small muted">${r[2]}</span></span><span aria-hidden="true">›</span></a>`).join('')}<a class="listrow" href="#/trainer/${DEMO}"><span><b>${X('My public page','Halaman awam saya')}</b><br><span class="small muted">${X('What employers see','Apa yang majikan lihat')}</span></span><span aria-hidden="true">›</span></a><a class="listrow" href="#/app/join"><span><b>${X('Start a new onboarding (demo)','Mulakan pendaftaran baharu (demo)')}</b><br><span class="small muted">${X('The sign-up flow a new trainer sees','Aliran pendaftaran yang dilihat jurulatih baharu')}</span></span><span aria-hidden="true">›</span></a></div>`}
function qrSvg(q,size,label){return `<span class="qr"><svg role="img" aria-label="${esc(label)}" viewBox="0 0 ${q.n} ${q.n}" width="${size}" height="${size}" shape-rendering="crispEdges"><path d="${q.d}" fill="#073421"/></svg></span>`}
function appPage(a,b){if(a==='join')return appShell('more',register());let body;
 if(!a)body=appHome();else if(a==='courses')body=appCourses();else if(a==='course-new')body=appCourseNew();else if(a==='id')body=appId();else if(a==='inbox')body=appInbox();else if(a==='more')body=appMore(b);else body=appHome();return appShell(a==='more'?'more':a,body)}

/* ========== router ========== */
function route(){const h=(location.hash||'#/').replace(/^#\/?/,'');const p=h.split('/');return [p[0]||'',p[1]||'',p[2]||'']}
function render(){const [r,a,b]=route();header();const app=document.getElementById('app');let html='';
 try{if(r==='')html=home();else if(r==='find')html=find();else if(r==='course')html=coursePage(a);else if(r==='ratings')html=ratings();else if(r==='trainer')html=report(a);else if(r==='employers')html=home();else if(r==='providers')html=providers();else if(r==='for-trainers')html=forTrainers();else if(r==='methodology')html=methodology();else if(r==='app')html=appPage(a,b);else if(r==='admin')html=admin();else html=`<h1>${X('Page not found','Halaman tidak ditemui')}</h1><a href="#/">${X('Home','Laman utama')}</a>`}
 catch(e){html=`<div class="note">${X('Something went wrong drawing this page','Ralat semasa memaparkan halaman ini')}: ${esc(e.message)}</div>`;if(window.console)console.error(e)}
 app.innerHTML=html;app.classList.toggle('appwrap',r==='app');
 document.title='OSH2U'+({'':' - '+X('Find OSH training you can trust','Cari latihan KKP yang boleh dipercayai'),find:' - '+X('Find training','Cari latihan'),ratings:' - '+X('Rated trainers','Jurulatih ditarafkan'),app:' - '+X('Trainer app','Aplikasi jurulatih')}[r]||'')}
let LAST='';function onRoute(){const h=location.hash;if(h===LAST)return;LAST=h;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',onRoute);

/* ========== events ========== */
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');
 if(!a){const row=e.target.closest('tr[data-go]');if(row&&!e.target.closest('a'))location.hash=row.dataset.go;return}
 const act=a.dataset.act;
 if(act==='lang'){regCollect();LANG=a.dataset.v;try{localStorage.setItem('osh2u.lang',LANG)}catch(x){}render()}
 if(act==='menu'){const n=document.getElementById('mainNav');const o=n.getAttribute('data-open')==='1';n.setAttribute('data-open',o?'0':'1');a.setAttribute('aria-expanded',!o)}
 if(act==='qchip'){e.preventDefault();FC=Object.assign({},FC,{spec:a.dataset.v,q:''});if(route()[0]==='find')render();else location.hash='#/find'}
 if(act==='enq'||act==='req'){e.preventDefault();openEnq(a.dataset.c,a.dataset.d,a.dataset.inhouse)}
 if(act==='close'){closeModal()}
 if(act==='rstep'){regCollect();const dir=+a.dataset.v;if(dir>0){const err=regValidate();if(err){document.getElementById('regErr').textContent=err;return}}REG.step=Math.max(1,Math.min(5,REG.step+dir));render();window.scrollTo(0,0)}
 if(act==='addcred'){regCollect();REG.d.creds.push({n:'',no:'',until:''});render()}
 if(act==='rsubmit'){regCollect();const err=regValidate();if(err){document.getElementById('regErr').textContent=err;return}const list=load('osh2u.registrations',[]);list.push(Object.assign({},REG.d,{at:new Date().toISOString(),uiLang:LANG}));save('osh2u.registrations',list);REG.done=true;render();window.scrollTo(0,0)}
 if(act==='caltoggle'){const A=appState();const d=a.dataset.d;A.cal[d]=dayState('app',d,A.cal)==='av'?'na':'av';A.availSet=true;appSave(A);render()}
 if(act==='ia'||act==='id'){const A=appState();A.inbox[a.dataset.id]=act==='ia'?'a':'d';appSave(A);render();toast(act==='ia'?X('Accepted. The employer gets your reply.','Diterima. Majikan menerima balasan anda.'):X('Declined. The employer has been told.','Ditolak. Majikan telah dimaklumkan.'))}
 if(act==='boost'){const A=appState();const d=new Date(TODAY);d.setDate(d.getDate()+30);A.boost[a.dataset.c]=iso(d);appSave(A);render();toast(X('Boosted for 30 days. Free during the pilot.','Dipromosi selama 30 hari. Percuma semasa perintis.'))}
 if(act==='qrused'){const A=appState();A.qrUsed=true;appSave(A);toast(X('Class code open for 48 hours.','Kod kelas dibuka selama 48 jam.'));render()}
 if(act==='copy'){const v=a.dataset.v;try{navigator.clipboard.writeText(v).then(()=>toast(X('Link copied','Pautan disalin')),()=>toast(v))}catch(x){toast(v)}}
 if(act==='wallet'){toast(X('Wallet passes come with the launch build.','Pas wallet disediakan dalam binaan pelancaran.'))}
 if(act==='lost'){const A=appState();A.claimed=false;appSave(A);render();toast(X('Card cancelled. A replacement is on its way.','Kad dibatalkan. Kad gantian sedang dihantar.'))}
 if(act==='csv'){const regs=load('osh2u.registrations',[]),leads=load('osh2u.leads',[]);const q=s=>'"'+String(s==null?'':s).replace(/"/g,'""')+'"';
  const csv=['type,name,email,state_or_company,detail,date'].concat(regs.map(r=>['registration',r.name,r.email,r.state,(r.creds||[]).map(c=>c.n).join('; '),r.at].map(q).join(',')),leads.map(l=>['enquiry',l.name,l.email,l.company,l.course||l.trainer,l.date].map(q).join(','))).join('\n');
  try{navigator.clipboard.writeText(csv).then(()=>toast(X('CSV copied','CSV disalin')),()=>{const t=document.getElementById('csvOut');t.className='';t.value=csv})}catch(x){const t=document.getElementById('csvOut');t.className='';t.value=csv}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function onFilter(e){const el=e.target;const f=el.dataset&&el.dataset.f,fc=el.dataset&&el.dataset.fc;
 if(f){F[f]=el.type==='checkbox'?el.checked:el.value;const r=document.getElementById('regT');if(r)r.innerHTML=regTable()}
 if(fc){FC[fc]=el.type==='checkbox'?el.checked:el.value;const r=document.getElementById('findR');if(r)r.innerHTML=findResults()}}
document.addEventListener('input',onFilter);document.addEventListener('change',onFilter);
document.addEventListener('submit',e=>{const f=e.target;
 if(f.id==='homeSearch'){e.preventDefault();const d=Object.fromEntries(new FormData(f));FC=Object.assign({},FC,{spec:d.spec||'',state:d.state||'',q:''});location.hash='#/find'}
 if(f.id==='reqF'){e.preventDefault();const d=Object.fromEntries(new FormData(f));const leads=load('osh2u.leads',[]);leads.push(Object.assign(d,ENQ,{at:new Date().toISOString(),uiLang:LANG}));save('osh2u.leads',leads);closeModal();toast(X('Enquiry sent. The trainer will reply to you directly.','Pertanyaan dihantar. Jurulatih akan membalas terus kepada anda.'))}
 if(f.id==='courseF'){e.preventDefault();const d=Object.fromEntries(new FormData(f));d.hrdc=!!d.hrdc;const A=appState();A.courses.push(d);appSave(A);location.hash='#/app/courses';toast(X('Published. It is live on Find training.','Diterbitkan. Kini dipaparkan di Cari latihan.'))}
 if(f.id==='claimF'){e.preventDefault();const v=document.getElementById('cc').value.replace(/[^a-z0-9]/gi,'');if(v.length<8){document.getElementById('ccErr').textContent=X('The code has 8 letters or numbers.','Kod ini mempunyai 8 huruf atau nombor.');return}const A=appState();A.claimed=true;appSave(A);render();toast(X('Card activated.','Kad diaktifkan.'))}
});
window.addEventListener('error',e=>{const b=document.getElementById('jsErr');if(b){b.hidden=false;b.textContent='Error: '+e.message}});
LAST=location.hash;render();
